function makeContent(pageName: string, profile: [string, string, string], isLocation: boolean): PageSeoContent {
  if (isLocation) {
    const heading = LOCATION_HEADING_TEMPLATES[hashIndex(`heading|${pageName}`, LOCATION_HEADING_TEMPLATES.length)](pageName);
    const introduction = LOCATION_INTRO_TEMPLATES[hashIndex(`intro|${pageName}`, LOCATION_INTRO_TEMPLATES.length)](pageName);
    const [t1, t2, t3] = LOCATION_BLOCK_TITLE_SETS[hashIndex(`blocks|${pageName}`, LOCATION_BLOCK_TITLE_SETS.length)](pageName);
    const extra = locationExtraBlocks[pageName.toLowerCase().replace(/&/g, "and").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "")];
    return {
      heading,
      introduction,
      blocks: [
        { title: t1, body: profile[0] },
        { title: t2, body: profile[1] },
        { title: t3, body: profile[2] },
        ...(extra ? [
          { title: `Venues and season notes for ${pageName}`, body: extra[0] },
          { title: `Choosing the right safa package in ${pageName}`, body: extra[1] },
        ] : []),
      ],
    };
  }
  return {
    heading: `${pageName}: styles, packages and booking guidance`,
    introduction: `A practical guide built around the service terms couples and families use when comparing professional safa tying in Mahabaleshwar.`,
    blocks: [
      { title: "What the service includes", body: profile[0] },
      { title: "Styles, colours and finishing", body: profile[1] },
      { title: "Price, packages and booking", body: profile[2] },
    ],
  };
}

export function getLocationSeoContent(slug: string, name: string): PageSeoContent {
  const profile = locationProfiles[slug];
  if (!profile) throw new Error(`Missing SEO content profile for location: ${slug}`);
  return makeContent(name, profile, true);
}

export function getServiceSeoContent(slug: string, name: string): PageSeoContent {
  const profile = serviceProfiles[slug];
  if (!profile) throw new Error(`Missing SEO content profile for service: ${slug}`);
  const base = makeContent(name, profile, false);
  const extra = serviceExtraBlocks[slug];
  if (!extra) return base;
  return { ...base, blocks: [...base.blocks, ...extra.map(([title, body]) => ({ title, body }))] };
}
